SELECT ?directorName ?rating WHERE {
  ?film wdt:P31 wd:Q11424;       # Film
        rdfs:label "Boxing Helena"@en;
        wdt:P57 ?director.
  ?director rdfs:label ?directorName FILTER (LANG(?directorName) = "en").
  ?film wdt:P1258 ?rating.       # age rating property
  FILTER (?rating = "15"@en || ?rating = "15")
  FILTER EXISTS {
    wd:Q10783 wdt:P106 wd:Q2526255.   # Martin Scorsese is a director
  }
}

SELECT ?director1 ?country1 ?director2 ?country2 WHERE {
  ?director1 wdt:P31 wd:Q5;        # director1 is a human
             wdt:P106 wd:Q2526255; # occupation: film director
             rdfs:label "Robert Stevenson"@en;
             wdt:P27 ?country1.    # country of citizenship for Robert Stevenson
  ?director2 wdt:P31 wd:Q5;
             wdt:P106 wd:Q2526255;
             wdt:P27 ?country2;
             wdt:P57 ?film.        # directed the film
  ?film rdfs:label "Romance of Astree and Celadon"@en.

  # Filter for different directors:
  FILTER(?director1 != ?director2)
}
LIMIT 1

SELECT ?director1 ?country1 ?director2 ?country2 WHERE {
  ?director1 wdt:P31 wd:Q5;        # director1 is a human
             wdt:P106 wd:Q2526255; # occupation: film director
             rdfs:label "Robert Stevenson"@en;
             wdt:P27 ?country1.    # country of citizenship for Robert Stevenson
  ?director2 wdt:P31 wd:Q5;
             wdt:P106 wd:Q2526255;
             wdt:P27 ?country2;
             wdt:P57 ?film.        # directed the film
  ?film rdfs:label "Romance of Astree and Celadon"@en.

  # Filter for different directors:
  FILTER(?director1 != ?director2)
}
LIMIT 1

SELECT ?player WHERE {
  {
    ?player wdt:P106 wd:Q5372.
    ?player wdt:P19 wd:Q1450.
    FILTER(CONTAINS(LCASE(STR(?player)), "angelique kerber"))
  }
  UNION
  {
    wd:Q1077148 wdt:P1346 ?event.
    ?event wdt:P710 ?player.
    ?player wdt:P106 wd:Q5372.
  }
}

