SELECT ?otherFilm ?otherFilmReleaseDate WHERE {
  BIND("Sacred Planet" AS ?sacredPlanetTitle)
  ?sacredPlanet wdt:P31 wd:Q11424;
                rdfs:label ?sacredPlanetTitle;
                wdt:P577 ?sacredPlanetReleaseDate.
  FILTER(LANG(?sacredPlanetTitle) = "en")

  ?otherFilm wdt:P31 wd:Q11424;
             wdt:P577 ?otherFilmReleaseDate;
             wdt:P161 ?actor.
  ?actor rdfs:label "Damion Poitier"@en.

  # Check that Damion Poitier has received awards
  ?actor wdt:P166 ?award.

  FILTER(?otherFilmReleaseDate < ?sacredPlanetReleaseDate)
}
ORDER BY DESC(?otherFilmReleaseDate)
LIMIT 10

